import{_ as o,o as r,c,a5 as t}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/graphics/gltf-mesh-buffers.svg",p=JSON.parse('{"title":"glTFのバッファから頂点とインデックスを読む","description":"","frontmatter":{"title":"glTFのバッファから頂点とインデックスを読む","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"GLBのJSONとBINを分け、buffer、bufferView、accessorから頂点属性とインデックスの型、位置、間隔を求める。範囲の検査とsparse accessorの読み方も扱う。","aliases":["glTF","GLB","bufferView","accessor","byteStride","componentType","POSITION","NORMAL","indices","interleaved","sparse accessor"],"verification":"KhronosのglTF 2.0仕様のバイナリ格納、メッシュ、GLB形式と照合"}},"headers":[],"relativePath":"graphics/mesh/gltf-mesh-buffers.md","filePath":"graphics/mesh/gltf-mesh-buffers.md"}'),d={name:"graphics/mesh/gltf-mesh-buffers.md"};function a(l,e,i,h,n,f){return r(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="gltfのバッファから頂点とインデックスを読む" tabindex="-1">glTFのバッファから頂点とインデックスを読む <a class="header-anchor" href="#gltfのバッファから頂点とインデックスを読む" aria-label="Permalink to &quot;glTFのバッファから頂点とインデックスを読む&quot;">​</a></h1><p>ゲームのパックから3Dモデルを取り出したあと、ローダーは「頂点の座標がどこから始まり、何バイトごとに次の頂点があるか」を求めます。glTF 2.0では、JSONがメッシュの構成や値の型を表し、座標やインデックスの実体はバイナリのバッファに置きます。例えば座標と法線が頂点ごとに交互に並んでいても、型と間隔をたどると、それぞれの値を取り出せます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#binary-data-storage" target="_blank" rel="noreferrer">KhronosのglTF 2.0バイナリ格納仕様</a> · <a href="/study/game/asset-pack-files.html">アセットパックの構成</a></p><h2 id="gltfと-glbでデータの置き場所が変わる" tabindex="-1"><code>.gltf</code>と<code>.glb</code>でデータの置き場所が変わる <a class="header-anchor" href="#gltfと-glbでデータの置き場所が変わる" aria-label="Permalink to &quot;`.gltf`と`.glb`でデータの置き場所が変わる&quot;">​</a></h2><p><code>.gltf</code>はJSON文書です。バッファの<code>uri</code>から外部の<code>.bin</code>などを参照したり、<code>data:</code> URIでバイト列を埋め込んだりできます。<code>.glb</code>は、同じglTFのJSONを<code>JSON</code>チャンクとして格納するバイナリコンテナーです。<code>BIN</code>チャンクが入っている場合、そこに格納したバッファは<code>buffers[0]</code>に対応し、その項目の<code>uri</code>は省略します。GLBから外部のリソースを参照することもできます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#glb-stored-buffer" target="_blank" rel="noreferrer">KhronosのGLBに格納するバッファの仕様</a></p><p>GLBの先頭12バイトには、識別子<code>glTF</code>、コンテナーのバージョン<code>2</code>、ファイル全体の長さが入ります。各チャンクは、データの長さと種類を示す8バイトに続いて、中身が並びます。<code>JSON</code>が先頭で、バッファを埋め込む場合は2番目に<code>BIN</code>を置きます。コンテナーの版とJSONの<code>asset.version</code>は別々に確認します。GLBの整数欄と、glTFで規定した頂点属性やインデックスのバイト列は、下位バイトを先に格納するリトルエンディアンです。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#binary-gltf-layout" target="_blank" rel="noreferrer">KhronosのGLBレイアウト</a> · <a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a></p><h2 id="位置、範囲、型を順にたどる" tabindex="-1">位置、範囲、型を順にたどる <a class="header-anchor" href="#位置、範囲、型を順にたどる" aria-label="Permalink to &quot;位置、範囲、型を順にたどる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>JSONの項目</th><th>確認すること</th></tr></thead><tbody><tr><td><code>meshes[].primitives[]</code></td><td><code>attributes.POSITION</code>や<code>attributes.NORMAL</code>は、対応する<code>accessors</code>の番号。<code>indices</code>もインデックス列を読むための<code>accessors</code>の番号。</td></tr><tr><td><code>accessors[]</code></td><td><code>bufferView</code>で読み取る範囲を選ぶ。<code>byteOffset</code>はその範囲の先頭からのずれ。<code>componentType</code>は1成分の型、<code>type</code>は1要素の形、<code>count</code>は要素数。</td></tr><tr><td><code>bufferViews[]</code></td><td><code>buffer</code>で元のバッファを選ぶ。<code>byteOffset</code>はバッファ先頭からのずれで、<code>byteLength</code>は範囲の長さ。頂点属性用の<code>byteStride</code>は要素の先頭から次の先頭までの距離。</td></tr><tr><td><code>buffers[]</code></td><td><code>byteLength</code>でバッファの論理長を知り、外部のデータやGLBの<code>BIN</code>から実体を得る。</td></tr></tbody></table><p>頂点の座標<code>POSITION</code>は、glTF 2.0の基本仕様では32ビット浮動小数点<code>5126</code>を3成分持つ<code>VEC3</code>です。要素1個は12バイトで、<code>count = 3</code>なら座標が3個あります。<code>POSITION</code>に必須の<code>min</code>と<code>max</code>は各成分の最小値と最大値です。ファイル内で読める範囲は、別にバイトの位置と長さから検査します。法線<code>NORMAL</code>も基本仕様では<code>5126</code>の<code>VEC3</code>です。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosのメッシュ属性とインデックスの仕様</a></p><p>同じ<code>bufferView</code>で座標と法線を交互に格納する例では、<code>byteStride</code>を24、座標の<code>accessor.byteOffset</code>を0、法線の<code>accessor.byteOffset</code>を12とします。頂点番号<code>i</code>に対応する属性の先頭は<code>bufferView.byteOffset + accessor.byteOffset + i × stride</code>です。<code>byteStride</code>の指定がなければ、ここで扱うスカラーとベクトルでは要素のサイズずつ進みます。行列を含む読み手は、列ごとの詰め物も仕様に従って扱います。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#data-alignment" target="_blank" rel="noreferrer">Khronosのaccessorとデータ整列の仕様</a></p><figure class="study-figure"><img src="'+s+'" alt="GLBのヘッダーとJSONに続くBINに、72バイトの頂点範囲と6バイトのインデックス範囲が入る。頂点の座標はバイト0、24、48から、法線は12、36、60から各12バイト。インデックス2、0、1はバイト72、74、76から各2バイト。バッファの論理長78バイトにゼロ2バイトを足してBINを整列する。" width="760" height="414" loading="lazy"><figcaption>座標と法線の1要素は各12バイトです。頂点ごとに両方を並べると、同じ属性の次の要素まで24バイト進みます。位置はバッファ先頭から数えています。<a href="/study/images/graphics/gltf-mesh-buffers.svg" target="_blank" rel="noopener noreferrer">バッファの配置図を拡大</a></figcaption></figure><p>図のインデックスは<code>SCALAR</code>で、1個が16ビットの符号なし整数<code>5123</code>です。値の並び<code>[2, 0, 1]</code>は、三角形を頂点2、0、1の順で組み立てる指定です。バイト列では<code>02 00 00 00 01 00</code>になります。各値は対応する頂点属性の<code>count</code>未満である必要があります。<code>indices</code>を省略したプリミティブは、頂点を0番から順に使います。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosのメッシュ仕様</a> · <a href="/study/graphics/mesh/vertex-and-index-input.html">頂点・インデックスの描画入力</a></p><h2 id="最後の要素まで入るかを確かめる" tabindex="-1">最後の要素まで入るかを確かめる <a class="header-anchor" href="#最後の要素まで入るかを確かめる" aria-label="Permalink to &quot;最後の要素まで入るかを確かめる&quot;">​</a></h2><p>GLBではヘッダーの全長と実際のファイル長を照合し、各チャンクがファイル内に収まるかを確認します。<code>BIN</code>チャンクを4バイト境界にそろえるために足す余白は最大3バイトです。この例では、バッファの<code>byteLength</code>が示す論理長78バイトにゼロを2バイト足します。<code>bufferView</code>の範囲検査には、余白を足す前の78バイトを使います。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#glb-stored-buffer" target="_blank" rel="noreferrer">KhronosのGLBのチャンクとバッファの仕様</a></p><p>次に、参照番号が各配列内にあり、<code>bufferView.byteOffset</code>と<code>bufferView.byteLength</code>で指定した範囲がバッファに収まることを確かめます。通常のスカラーやベクトルのaccessorで最後に使う範囲の終端は、ビューの先頭を基準に<code>accessor.byteOffset + (count − 1) × stride + 要素サイズ</code>です。この例の法線なら<code>12 + (3 − 1) × 24 + 12 = 72</code>で、頂点のビューにちょうど収まります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#data-alignment" target="_blank" rel="noreferrer">Khronosのaccessor整列と範囲の仕様</a></p><p>実装では型、整列、ストライドの制約を先に確認し、<code>count</code>が1以上かを調べます。終端を計算する前に、<code>accessor.byteOffset</code>と要素1個分をビューの長さから引けるかを順に確かめます。残りを正のストライドで割り、その商が<code>count − 1</code>以上なら、最後の要素まで収まります。加算や乗算の桁あふれを避けたうえで、インデックスの値そのものも検査できます。<a href="/study/data/binary-file-validation.html">バイナリファイルの範囲検査</a></p><h2 id="数値の変換とsparse-accessor" tabindex="-1">数値の変換とsparse accessor <a class="header-anchor" href="#数値の変換とsparse-accessor" aria-label="Permalink to &quot;数値の変換とsparse accessor&quot;">​</a></h2><p><code>normalized: true</code>を使える整数属性では、値を取り出すときに符号なしなら<code>[0, 1]</code>、符号付きなら<code>[-1, 1]</code>へ変換します。例えば8ビットの符号なし頂点色で<code>128</code>は<code>128 / 255</code>になります。<code>NORMAL</code>が単位長のベクトルを表すことと、整数の符号化に使う<code>normalized</code>は別の規則です。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#_accessor_normalized" target="_blank" rel="noreferrer">Khronosのnormalizedの仕様</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">メッシュ属性の仕様</a></p><p><code>sparse</code>付きのaccessorでは、元の配列の一部を別の値で上書きします。元の<code>bufferView</code>を省略した場合は、全要素をゼロで初期化します。<code>sparse.indices</code>は置き換える要素番号なので、描画時に頂点を選ぶプリミティブの<code>indices</code>とは役割が異なります。読み手は置換用の番号列と値列にも範囲の検査を行い、番号が重複なしの昇順で、いずれも元の要素数未満かを確かめます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#sparse-accessors" target="_blank" rel="noreferrer">Khronosのsparse accessorの仕様</a></p><p>C++実践では、プログラムが生成したGLBのJSONを既知の内容と照合し、その配置に従って<code>BIN</code>から座標とインデックスを読みます。D3D12のソフトウェアアダプターWARPで画面外の描画先へ三角形を描き、ピクセルを読み戻して確認します。汎用ローダーでは、JSONから参照先と型をたどり、対応する拡張や各形式の規則に従って描画入力を組み立てます。<a href="/study/practice/graphics/glb-mesh-observation.html">GLBから三角形を描くC++実践</a></p>',19)])])}const b=o(d,[["render",a]]);export{p as __pageData,b as default};
